const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const sanJuan = ee.Geometry.Point([-66.1057, 18.4663]).buffer(5000); // 5km buffer around San Juan
    const collectionId = 'NOAA/VIIRS/DNB/COMPOSITE_V1/VNP46A1';
    const band = 'DNB_BRDF_Corrected_NTL';

    const date1_start = '2017-09-01';
    const date1_end = '2017-09-03'; // End date is exclusive

    const date2_start = '2017-09-27';
    const date2_end = '2017-09-29'; // End date is exclusive

    // Function to process an image collection for a given period
    const getMeanBrightness = (start, end, geometry) => {
        const collection = ee.ImageCollection(collectionId)
            .filterDate(start, end)
            .filterBounds(geometry)
            .select([band, 'Mandatory_Quality_Flag']);

        const size = collection.size().getInfo();
        if (size === 0) {
            return { mean: null, pixels: 0, image_count: 0 };
        }

        // Keep only high-quality pixels (Flag == 0)
        const qualityMask = (image) => {
            const quality = image.select('Mandatory_Quality_Flag').eq(0);
            return image.updateMask(quality);
        };

        const image = collection.map(qualityMask).select(band).mean();

        const stats = image.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: 500,
            maxPixels: 1e9
        });

        return {
            mean: stats.get(band + '_mean').getInfo(),
            pixels: stats.get(band + '_count').getInfo(),
            image_count: size
        };
    };

    // 2. Data Acquisition & Processing
    const period1_stats = getMeanBrightness(date1_start, date1_end, sanJuan);
    const period2_stats = getMeanBrightness(date2_start, date2_end, sanJuan);

    // 3. Validation & Evidence
    console.log(`Sep 1-2, 2017: Images=${period1_stats.image_count}, Brightness=${period1_stats.mean !== null ? period1_stats.mean.toFixed(2) : 'N/A'}, Pixels=${period1_stats.pixels}`);
    console.log(`Sep 27-28, 2017: Images=${period2_stats.image_count}, Brightness=${period2_stats.mean !== null ? period2_stats.mean.toFixed(2) : 'N/A'}, Pixels=${period2_stats.pixels}`);

    // Check for C1: Empty Collection
    if (period1_stats.image_count === 0 || period2_stats.image_count === 0) {
        console.log('Evidence: No images found for one or both periods.');
        console.log('A');
        return;
    }

    // Check for C2: No Valid Pixels
    if (period1_stats.pixels === 0 || period2_stats.pixels === 0) {
        console.log('Evidence: After quality masking, no valid pixels remained in the area of interest.');
        console.log('C2');
        return;
    }

    // Check for C3: Calculation Failure
    if (period1_stats.mean === null || period2_stats.mean === null) {
        console.log('Evidence: The mean brightness could not be calculated.');
        console.log('C3');
        return;
    }

    // 4. Final Answer
    if (period2_stats.mean < period1_stats.mean) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(error => {
    console.error('An error occurred:', error);
    console.log('D');
});
